fn max(a: &Vec<i32>, n: usize) -> i32 {
    // Preconditions (for debug builds; can be removed in release):
    // - n > 0
    // - n <= a.len()
    // - n < 1000
    debug_assert!(n > 0, "n must be strictly positive");
    debug_assert!(n <= a.len(), "n must not exceed the array length");
    debug_assert!(n < 1000, "n must be less than 1000");

    // Initialize the maximum with the first element
    let mut max_val = a[0];

    // Scan the remaining first n elements
    for i in 1..n {
        if a[i] > max_val {
            max_val = a[i];
        }
    }

    max_val
}

